var score: int = 0
var lives: int = 3
@onready var score_label: Label = $ScoreLabel
@onready var lives_label: Label = $LivesLabel
@onready var music_player: AudioStreamPlayer = $MusicPlayer
@onready var star_player: AudioStreamPlayer = $StarPlayer
@onready var rock_player: AudioStreamPlayer = $RockPlayer
@onready var game_over_player: AudioStreamPlayer = $GameOverPlayer


func _ready() -> void:
	update_ui()
	music_player.play()


func collect_star() -> void:
	score += 1
	update_ui()
	star_player.pitch_scale = randf_range(0.9, 1.1)
	star_player.play()


func hit_rock() -> void:
	lives -= 1
	update_ui()
	rock_player.play()
	if lives <= 0:
		game_over()


func game_over() -> void:
	music_player.stop()
	game_over_player.play()


func update_ui() -> void:
	score_label.text = "Stelle: %d" % score
	lives_label.text = "Vite: %d" % lives

