extends Node2D

@onready var music_player: AudioStreamPlayer = $MusicPlayer
@onready var star_player: AudioStreamPlayer = $StarPlayer


func _ready() -> void:
	# Avvia la musica di sottofondo appena la scena è pronta
	music_player.play()


func play_star_sound() -> void:
	# Varia leggermente l'intonazione per rendere ogni presa unica
	star_player.pitch_scale = randf_range(0.9, 1.1)
	star_player.play()

extends Node2D

@onready var music_player: AudioStreamPlayer = $MusicPlayer
@onready var star_player: AudioStreamPlayer = $StarPlayer
@onready var rock_player: AudioStreamPlayer = $RockPlayer
@onready var game_over_player: AudioStreamPlayer = $GameOverPlayer


func _ready() -> void:
	music_player.play()


func on_star_collected() -> void:
	star_player.pitch_scale = randf_range(0.92, 1.08)
	star_player.play()


func on_rock_hit() -> void:
	rock_player.pitch_scale = randf_range(0.95, 1.05)
	rock_player.play()


func on_game_over() -> void:
	# Ferma la musica per dare risalto al segnale di fine partita
	music_player.stop()
	game_over_player.play()
